
"use client";

// Generated by philote from component SwipeDeck (deck). Do not edit.
import { useState } from "react";

import { toast } from "sonner";
import type { SwipeDeckProps } from "@/lib/reads";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import Mark from "@/components/common/mark";

import { swipe } from "@/lib/actions/swipe-deck-call";

export default function SwipeDeck({ deck }: SwipeDeckProps) {

    const [index, setIndex] = useState(0);
    const [busy, setBusy] = useState(false);
    const [matched, setMatched] = useState(false);
    const item = deck[index];

    async function decide(choice: boolean) {
        if (!item || busy) return;
        setBusy(true);
        const res = await swipe({ target: item.id, liked: choice });
        setBusy(false);
        if (!res.ok) {
            toast.error(res.error);
            return;
        }
        if (res.value.match) {
            setMatched(true);
        }
        setIndex((i) => i + 1);
    }
    if (matched) {
        return (
            <Card className="mx-auto max-w-md text-center">
                <CardHeader>
                    <CardTitle className="font-heading text-2xl">{"It's a match!"}</CardTitle>
                </CardHeader>
                <CardContent className="pb-6">
                    <Button onClick={() => setMatched(false)}>
                        {"Keep swiping"}
                    </Button>
                </CardContent>
            </Card>
        );
    }

    if (!item) {
        return (
            <Card className="mx-auto max-w-md text-center">
                <CardContent className="py-12 text-sm text-muted-foreground">
                    {"You've seen every horse. Check back later."}
                </CardContent>
            </Card>
        );
    }

    return (
        <div className="mx-auto max-w-md space-y-4">
            <Card>
                <CardHeader className="flex flex-col items-center gap-3 text-center">
                    <Mark name={item.name} className="size-24" />
                    <CardTitle className="font-heading text-2xl">{item.name}</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="flex flex-wrap items-center justify-center gap-2 text-sm text-muted-foreground">
                        <span><span className="tabular-nums">{item.age.toLocaleString("en")}</span></span>
                        <span><Badge variant="secondary">{item.breed}</Badge></span>
                    </div>
                    <p className="text-center text-sm leading-relaxed text-muted-foreground">{item.bio}</p>
                </CardContent>
            </Card>
            <div className="flex items-center justify-center gap-4">
                <Button variant="outline" size="lg" disabled={busy} onClick={() => decide(false)} aria-label="Pass">
                    ✕
                </Button>
                <Button size="lg" disabled={busy} onClick={() => decide(true)} aria-label="Like">
                    ♥
                </Button>
            </div>
        </div>
    );
}
